create index on leads (business_id, state);

create table lead_scores (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references organizations (id) on delete cascade,
  lead_id       uuid not null references leads (id) on delete cascade,
  score         numeric(5, 2) not null,
  criteria      jsonb not null,                      -- [{key, weight, value, reason}]
  computed_at   timestamptz not null default now()
);

-- ---------------------------------------------------------------- AI execution
create table ai_conversations (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references organizations (id) on delete cascade,
  business_id   uuid not null references business_profiles (id) on delete cascade,
  user_id       uuid references app_users (id) on delete set null,
  title         text,
  created_at    timestamptz not null default now()
);

create table ai_messages (
  id              uuid primary key default gen_random_uuid(),
  org_id          uuid not null references organizations (id) on delete cascade,
  conversation_id uuid not null references ai_conversations (id) on delete cascade,
  role            text not null check (role in ('user','assistant','tool','system')),
  content         text not null,
  citations       jsonb not null default '[]',       -- [{kind, id, label}]
  agent_run_id    uuid,
  created_at      timestamptz not null default now()
);
create index on ai_messages (conversation_id, created_at);

create table agent_runs (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references organizations (id) on delete cascade,
  business_id   uuid not null references business_profiles (id) on delete cascade,
  agent         agent_kind not null,
  state         agent_run_state not null default 'queued',
  input         jsonb not null default '{}',
  output        jsonb,
  error         text,
  prompt_tokens int,
  output_tokens int,
  cost_usd      numeric(10, 5),
  started_at    timestamptz,
  finished_at   timestamptz,
  created_at    timestamptz not null default now()
);
create index on agent_runs (business_id, agent, created_at desc);

-- ---------------------------------------------------------------- reporting, ops
create table reports (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references organizations (id) on delete cascade,
  business_id   uuid not null references business_profiles (id) on delete cascade,
  kind          report_kind not null,
  title         text not null,
  storage_ref   text,                                -- object storage key, not a public URL
  payload       jsonb not null default '{}',
  created_at    timestamptz not null default now()
);

create table integrations (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references organizations (id) on delete cascade,
  kind          integration_kind not null,
  status        text not null default 'disconnected',
  external_id   text,
  token_ref     text,                                -- secret store reference only
  scopes        text[] not null default '{}',
  connected_at  timestamptz,
  created_at    timestamptz not null default now(),
  unique (org_id, kind, external_id)
);

create table notifications (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references organizations (id) on delete cascade,
  user_id       uuid references app_users (id) on delete cascade,
  kind          text not null,
  body          text not null,
  read_at       timestamptz,
  created_at    timestamptz not null default now()
);

create table audit_logs (
  id            bigserial primary key,
  org_id        uuid references organizations (id) on delete set null,
  actor_user_id uuid references app_users (id) on delete set null,
  action        text not null,
  target        text,
  metadata      jsonb not null default '{}',
  ip            inet,
  created_at    timestamptz not null default now()
);
create index on audit_logs (org_id, created_at desc);

-- ---------------------------------------------------------------- updated_at
create or replace function touch_updated_at() returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['app_users','organizations','business_profiles','recommendations','growth_tasks','leads']
  loop
    execute format('create trigger %I_touch before update on %I for each row execute function touch_updated_at()', t, t);
  end loop;
end $$;



-- ============================================================ db/policies/0002_rls.sql

-- Row-level security: the tenant boundary is enforced by Postgres, not by application code.
-- The app sets `app.user_id` per connection (Supabase derives it from the JWT via auth.uid()).
--
-- The per-table block below is written out in full rather than generated by a DO loop. A loop is
-- shorter, but a reviewer cannot see which tables are protected without executing it, and the CI
-- check in scripts/check_schema.py could not verify it statically either.

create or replace function app_current_user() returns uuid
language sql stable as $$
  select nullif(current_setting('app.user_id', true), '')::uuid
$$;

create or replace function is_org_member(target uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from org_members m
     where m.org_id = target and m.user_id = app_current_user()
  )
$$;

create or replace function is_org_admin(target uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from org_members m
     where m.org_id = target and m.user_id = app_current_user()
       and m.role in ('owner', 'admin')
  )
$$;

alter table business_profiles enable row level security;
alter table business_profiles force row level security;
create policy business_profiles_read   on business_profiles for select using (is_org_member(org_id));
create policy business_profiles_write  on business_profiles for insert with check (is_org_member(org_id));
create policy business_profiles_update on business_profiles for update using (is_org_member(org_id)) with check (is_org_member(org_id));
create policy business_profiles_delete on business_profiles for delete using (is_org_admin(org_id));
