alter table app_users enable row level security;
create policy app_users_self on app_users for select
  using (
    id = app_current_user()
    or exists (select 1 from org_members m where m.user_id = app_users.id and is_org_member(m.org_id))
  );

-- Audit logs are append-only. No update or delete policy is created on purpose, and the grants are
-- revoked, so the table is immutable to every application role.
alter table audit_logs enable row level security;
create policy audit_logs_read  on audit_logs for select using (org_id is null or is_org_member(org_id));
create policy audit_logs_write on audit_logs for insert with check (true);
revoke update, delete on audit_logs from public;



-- ============================================================ db/migrations/0003_supabase_auth.sql

-- Supabase-specific wiring: the tenant helper reads the JWT, and every new auth user gets an app row.
-- Everything else in 0001/0002 is portable Postgres and stays that way on purpose.

-- auth.uid() is the supported reader: it parses request.jwt.claims. The legacy
-- request.jwt.claim.sub setting is empty on current PostgREST, which made this return null and every
-- authenticated RPC fail with 28000.
create or replace function app_current_user() returns uuid
language sql stable as $$
  select coalesce(
    auth.uid(),
    nullif(current_setting('app.user_id', true), '')::uuid
  );
$$;

-- Mirror auth.users into app_users so FKs point at a table we control.
create or replace function sync_auth_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  -- display_name is NOT NULL here, and sign-up metadata is optional, so fall back to the email's local
  -- part rather than failing the whole signup. The first version of this function referenced a
  -- full_name column that does not exist, and every signup returned a 500.
  insert into app_users (id, email, display_name)
  values (
    new.id,
    new.email,
    coalesce(
      nullif(new.raw_user_meta_data->>'full_name', ''),
      nullif(new.raw_user_meta_data->>'name', ''),
      split_part(new.email, '@', 1)
    )
  )
  on conflict (id) do update
    set email = excluded.email,
        display_name = coalesce(nullif(app_users.display_name, ''), excluded.display_name),
        updated_at = now();
  return new;
end $$;

drop trigger if exists on_auth_user_sync on auth.users;
create trigger on_auth_user_sync
  after insert or update of email on auth.users
  for each row execute function sync_auth_user();

-- RLS policies are inert for the anon/authenticated roles unless the role may reach the table at all.
do $$
declare t text;
begin
  for t in select tablename from pg_tables where schemaname = 'public' loop
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('grant all on public.%I to service_role', t);
  end loop;
end $$;



-- ============================================================ db/migrations/0004_workspace.sql

-- One round trip creates a tenant: org, owner membership and business profile, atomically.
-- Client-side inserts would race the RLS policy that requires membership to already exist, which is
-- exactly the chicken-and-egg that produces half-created workspaces in production.

create or replace function create_workspace(
  p_business_name text,
  p_website_url   text default null,
  p_industry      text default null,
  p_description   text default null,
  p_target_audience text default null,
  p_challenges    text[] default '{}',
  p_org_name      text default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := app_current_user();
  v_org  uuid;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if coalesce(btrim(p_business_name), '') = '' then
    raise exception 'business name is required' using errcode = '22023';
  end if;

  -- organizations.slug is NOT NULL and unique, so derive it: readable prefix plus a short suffix that
  -- makes collisions vanishingly unlikely without a retry loop.
  insert into organizations (name, slug, created_by)
  values (
    coalesce(nullif(btrim(p_org_name), ''), p_business_name),
    lower(regexp_replace(btrim(coalesce(nullif(btrim(p_org_name), ''), p_business_name)), '[^a-zA-Z0-9]+', '-', 'g'))
      || '-' || substr(md5(random()::text), 1, 6),
    v_user
  )
  returning id into v_org;

  insert into org_members (org_id, user_id, role) values (v_org, v_user, 'owner');

  insert into business_profiles (org_id, name, website_url, industry, description, target_audience, challenges)
  values (v_org, btrim(p_business_name), nullif(btrim(p_website_url), ''), nullif(btrim(p_industry), ''),
          nullif(btrim(p_description), ''), nullif(btrim(p_target_audience), ''), coalesce(p_challenges, '{}'));

  return v_org;
end $$;

revoke all on function create_workspace(text, text, text, text, text, text[], text) from public;
grant execute on function create_workspace(text, text, text, text, text, text[], text) to authenticated;

-- The dashboard's single read: this user's workspaces with the profile attached.
-- The view is created after 0002's blanket grant loop, so it needs its own privileges: without them
-- PostgREST hides it from the schema cache and the app fails with
-- "Could not find the table 'public.my_workspaces'". security_invoker keeps the caller's RLS in force
-- on top of the explicit membership filter, so the view cannot widen anyone's visibility.
create or replace view my_workspaces with (security_invoker = true) as
  select o.id as org_id, o.name as org_name, o.plan, m.role,
         p.id as profile_id, p.name as business_name, p.industry, p.website_url, p.description
  from organizations o
  join org_members m on m.org_id = o.id and m.user_id = app_current_user()
  left join business_profiles p on p.org_id = o.id and p.deleted_at is null
  where o.deleted_at is null;

revoke all on my_workspaces from anon;
grant select on my_workspaces to authenticated, service_role;
notify pgrst, 'reload schema';
